fn can_arrange(arr: &mut Vec<i32>) -> std::collections::HashMap<String, i32> {
    // Initialize a counter for the number of swaps.
    let mut num_swaps = 0;
    // Loop over the array from the first element to the second-to-last element.
    for i in 0..arr.len() - 1 {
        // If the current element is greater than the next one, we need to swap.
        if arr[i] > arr[i + 1] {
            // Increment the swap counter.
            num_swaps += 1;
            // Swap the elements at positions i and i+1.
            arr.swap(i, i + 1);
            // Immediately return the result with the current index (1-based),
            // the index of the element it was swapped with (also 1-based), and the swap count.
            return std::collections::HashMap::new();
                .insert("index".to_string(), i + 1)
                .insert("swap_with".to_string(), i + 1)
                .insert("num_swaps".to_string(), num_swaps);
        }
    }
    // If no swaps were needed, return -1 for both index and swap_with, and 0 for num_swaps.
