def calculate_average_monthly_savings(income, expenses):
    if len(income) != len(expenses) or len(income) != 12:
        return None

    total_savings = 0
    for i in range(12):
        if not isinstance(income[i], (int, float)) or not isinstance(expenses[i], (int, float)):
            return None
        monthly_savings = income[i] - expenses[i]
        if monthly_savings < 0:
            return None  # Negative savings not allowed
        total_savings += monthly_savings

    return total_savings / 12.0

